import itertools
n=13
for mapping in ['ck=Ck','array0']:
    count=0; best=999; bestdata=None
    for seq in itertools.product([-1,1], repeat=n):
        if seq[8]!=1 or seq[10]!=-1: continue
        C=[None]+[sum(seq[i]*seq[i+k] for i in range(n-k)) for k in range(1,n)]
        E=sum(C[k]*C[k] for k in range(1,n))
        if mapping=='ck=Ck':
            ok=(C[4]==2 and C[5]==-1)
        else:
            # c[4]=C5 c[5]=C6
            ok=(C[5]==2 and C[6]==-1)
        if ok:
            count+=1
            if E<best:
                best=E; bestdata=(seq,C[1:])
    print(mapping, 'count', count, 'best', best, bestdata)
